escenas.animacion:
const W=A.W, acc=A.accent, WH='#FFFFFF', RED='#FF4D5E', GRN='#3DDC84', DK='#0B1630';
A.bg('#0B1630','#050A18',true);
const kVec=A.k('veces',0.333), kPier=A.k('pierdes',1.333), kGan=A.k('ganas',2.0), kSue=A.k('sueño.',3.333), kQui=A.k('¿Quién',3.667), kDec=A.k('decide',4.0), kPara=A.k('para',5.0);

// ---- hour value
const p1=A.p(kPier,0.6,'whip'), p2=A.p(kGan+0.08,0.6,'whip');
let h = t<kGan ? 2+p1 : 2-p2;
const phase = t<kPier?0:(t<kGan?1:2);

// ---- clock transform
const pin=A.p(0,0.6,'snapSettle');
const pmove=A.p(kQui,0.6,'glide');
const cx=A.lerp(540,330,pmove), cy=A.lerp(760,730,pmove);
const bump = 1+0.06*Math.sin(Math.PI*A.clamp((t-kGan)/0.18));
const sc=A.lerp(1,0.66,pmove)*A.lerp(0.6,1,pin)*(t>kGan?bump:1);
const shk=((t>kPier+0.5&&t<kPier+0.75)||(t>kGan+0.58&&t<kGan+0.83))?6:0;

A.with(()=>{
  const R=270;
  const pts=[];for(let i=0;i<40;i++){const a=i/40*Math.PI*2;pts.push([cx+Math.cos(a)*R,cy+Math.sin(a)*R]);}
  A.circle(cx,cy,R,{fill:'#101E3D',stroke:WH,lw:8});
  A.lib.hatch(ctx,pts.filter((p,i)=>i>5&&i<25).concat([[cx,cy]]),{angle:0.7,spacing:16,width:1.5,color:'rgba(79,216,255,0.16)'});
  for(let i=0;i<60;i++){
    const a=i/60*Math.PI*2, big=i%5===0, r1=big?R-40:R-20;
    A.line([[cx+Math.cos(a)*r1,cy+Math.sin(a)*r1],[cx+Math.cos(a)*(R-10),cy+Math.sin(a)*(R-10)]],{stroke:big?WH:'rgba(255,255,255,0.4)',lw:big?7:3});
  }
  for(let n=1;n<=12;n++){const a=n/12*Math.PI*2-Math.PI/2;A.text(String(n),cx+Math.cos(a)*(R-78),cy+Math.sin(a)*(R-78)+14,{size:40,color:WH,weight:'700',align:'center'});}
  const a0=-Math.PI/2;
  if(phase===1 && t<kPier+1.0){
    const fa=1-A.p(kPier+0.6,0.4,'softInOut');
    ctx.save();ctx.strokeStyle=RED;ctx.globalAlpha=0.4*fa;ctx.lineWidth=56;ctx.beginPath();
    ctx.arc(cx,cy,R-150,a0,a0+Math.max(0.001,p1*Math.PI*2),false);ctx.stroke();ctx.restore();
  }
  if(phase===2 && t<kGan+1.1){
    const fa=1-A.p(kGan+0.7,0.4,'softInOut');
    ctx.save();ctx.strokeStyle=GRN;ctx.globalAlpha=0.4*fa;ctx.lineWidth=56;ctx.beginPath();
    ctx.arc(cx,cy,R-150,a0,a0-Math.max(0.001,p2*Math.PI*2),true);ctx.stroke();ctx.restore();
  }
  const ma=(h-Math.floor(h))*Math.PI*2-Math.PI/2, ha=(h/12)*Math.PI*2-Math.PI/2;
  A.line([[cx,cy],[cx+Math.cos(ha)*140,cy+Math.sin(ha)*140]],{stroke:WH,lw:16});
  A.line([[cx,cy],[cx+Math.cos(ma)*215,cy+Math.sin(ma)*215]],{stroke:acc,lw:10});
  A.circle(cx,cy,16,{fill:acc});
  const hh=Math.floor(h+1e-4), mm=Math.min(59,Math.floor((h-hh)*60+1e-4));
  const dc = phase===0?acc:(phase===1?RED:GRN);
  A.label(String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0'),cx,cy+115,{size:50,bg:'#050A18',color:dc});
},{x:cx,y:cy,scale:sc,alpha:pin,shake:shk});

// ---- calendars MAR / OCT (raised: bottom edge ~1080)
function ffIcon(x,y,dir,col){
  for(let j=0;j<2;j++){
    const ox=x+dir*(j*22-11);
    ctx.save();ctx.fillStyle=col;ctx.beginPath();
    ctx.moveTo(ox-dir*14,y-16);ctx.lineTo(ox+dir*14,y);ctx.lineTo(ox-dir*14,y+16);ctx.closePath();ctx.fill();ctx.restore();
  }
}
const pCal=A.p(kVec,0.5,'softLand')*(1-A.p(kQui,0.35,'accelExit'));
if(pCal>0.01){
  [['MAR',-1,'−1h',RED,1],['OCT',1,'+1h',GRN,2]].forEach(([m,side,txt,col,ph],i)=>{
    const x=540+side*420, y=1000, lit=phase===ph;
    const litP = ph===1 ? A.p(kPier,0.3,'softLand')*(1-A.p(kGan,0.25,'softInOut')) : A.p(kGan,0.3,'softLand');
    const s=A.pop(kVec+i*0.2)*(1+0.08*litP);
    const dim = phase===0?1:A.lerp(0.45,1,litP);
    A.with(()=>{
      if(litP>0.01) A.rect(x-100,y-80,200,160,{r:20,fill:col,alpha:0.25*litP,glow:30});
      A.rect(x-100,y-80,200,160,{r:20,fill:'#101E3D',stroke:lit?col:WH,lw:lit?7:5});
      A.rect(x-100,y-80,200,52,{r:20,fill:litP>0.5?col:acc});
      A.text(m,x,y-40,{size:40,color:DK,weight:'900',align:'center'});
      ffIcon(x-48,y+32,side===-1?1:-1,lit?col:WH);
      A.text(txt,x+38,y+48,{size:46,color:lit?col:WH,weight:'900',align:'center'});
    },{x,y,scale:s,alpha:pCal*dim});
  });
}

// ---- -1 / +1 pills
const kPlus=kGan+0.55;
if(t>kPier&&t<kGan){
  const s=A.pop(kPier+0.45,0.4);
  A.label('−1 HORA',540,1065,{size:54,bg:RED,color:WH,scale:s});
  A.rings(540,760,kPier+0.55,{count:2,color:RED,maxR:380,lw:5});
}
if(t>=kGan&&t<kQui){
  const s=A.pop(kPlus,0.4)*(1-A.p(kQui-0.25,0.25,'accelExit'));
  A.label('+1 HORA',540,1065,{size:54,bg:GRN,color:DK,scale:s});
  A.rings(540,760,kGan+0.65,{count:2,color:GRN,maxR:380,lw:5});
}

// ---- sleep bar: 8h -> 7h (pierdes) -> 8h -> 9h (+1 hora)
const pOut=A.p(kPara,0.65,'softInOut');
const pBar=A.p(0,0.5,'softLand')*(1-pOut);
if(pBar>0.01){
  let hrs;
  if(t<kGan) hrs=8-A.p(kPier+0.15,0.55,'glide');
  else hrs=7+A.p(kGan,0.25,'softInOut')+A.p(kPlus,0.6,'glide');
  const x0=200,y0=1480+40*pOut,bw=680, len=hrs/9;
  const bc = phase===0?acc:(phase===1?RED:GRN);
  A.text('SUEÑO',x0,y0-30,{size:46,color:WH,weight:'800',alpha:pBar});
  A.rect(x0,y0,bw,70,{r:35,stroke:'rgba(255,255,255,0.5)',lw:4,alpha:pBar});
  A.rect(x0+6,y0+6,(bw-12)*len,58,{r:29,fill:bc,alpha:pBar});
  const growPulse = phase===2 ? 1+0.12*Math.sin(Math.PI*A.clamp((t-kPlus-0.45)/0.3)) : 1;
  A.with(()=>{A.text(Math.round(hrs)+' h',x0+bw,y0-30,{size:52,color:bc,weight:'900',align:'right',alpha:pBar});},{x:x0+bw-50,y:y0-45,scale:growPulse});
  if(phase>0){
    const gw=(bw-12)/9, gx=x0+6+gw*(phase===1?7:8);
    A.rect(gx,y0+6,gw,58,{r:10,stroke:phase===1?bc:WH,lw:3,dash:[8,8],alpha:pBar*0.9});
    A.text(phase===1?'−1 h':'+1 h',gx+gw/2,y0+125,{size:40,color:bc,weight:'800',align:'center',alpha:pBar*A.p(phase===1?kPier+0.3:kPlus,0.3)});
  }
}

// ---- Zzz
if(t>kSue-0.1&&t<kQui+0.6){
  A.particles(3,7,(i,rnd)=>{const st=kSue+i*0.2, q=A.clamp((t-st)/1.1);if(q<=0||q>=1)return;
    A.text('Z',850+i*55+Math.sin(q*6)*12,640-i*40-q*120,{size:52+i*16,color:WH,weight:'900',alpha:Math.sin(q*Math.PI)*(1-pmove)});});
}

// ---- big question mark with one clean full pulse
if(t>kQui){
  const s=A.pop(kQui,0.5);
  const wob=Math.sin((t-kQui)*3)*0.06;
  const q=A.clamp((t-kQui-0.2)/0.8);
  if(q>0&&q<1){
    const r=A.lerp(140,300,1-Math.pow(1-q,3));
    ctx.save();ctx.strokeStyle=acc;ctx.lineWidth=A.lerp(12,2,q);ctx.globalAlpha=0.8*(1-q);
    ctx.beginPath();ctx.arc(780,720,r,0,Math.PI*2);ctx.stroke();ctx.restore();
  }
  A.with(()=>{A.text('?',780,900,{size:520,color:acc,weight:'900',align:'center',stroke:'#050A18',strokeWidth:10});},{x:780,y:720,scale:s,rot:wob,shake:t<kQui+0.3?10:0});
  if(t>kDec){const sd=A.pop(kDec,0.4);A.label('¿QUIÉN?',780,1020,{size:58,bg:WH,color:DK,scale:sd});}
}

// ---- ¿PARA QUÉ? + bulb (enters while sleep bar fades)
if(t>kPara){
  const s=A.pop(kPara+0.1,0.5);
  A.label('¿PARA QUÉ?',470,1520,{size:84,bg:acc,color:DK,scale:s,alpha:A.p(kPara,0.4,'softInOut')});
  const sb=A.pop(kPara+0.3,0.45);
  A.with(()=>{A.bulb(900,1500,{scale:1,on:A.p(A.k('qué',5.333),0.4,'softInOut')});},{x:900,y:1500,scale:sb});
  A.flash(kPara+0.1,0.2,0.2);
}

A.bg('#0a1626', '#050b14', true);
const acc = A.accent;
const kNo = A.k('no', 0.667);
const k2 = A.k('cambia', 2.0, 2);
const kRel = A.k('reloj', 3.0);
const kAc = A.k('acordamos', 3.667);

// ---------- TIERRA ----------
const pT = A.p(k2 - 0.15, 0.75, 'whip');
const ex = A.lerp(540, 270, pT), ey = A.lerp(740, 1530, pT), er = A.lerp(250, 115, pT);
const eScale = A.pop(0.0, 0.5);
const rot = t * 0.9;

// sol (solo en la fase 1)
const sunA = 1 - A.p(k2 - 0.2, 0.4, 'softInOut');
if (sunA > 0.01) {
  A.with(() => {
    A.sun(120, 740, 55);
    for (let i = 0; i < 4; i++) {
      const yy = 640 + i * 65;
      A.arrow(190, yy, 270, yy, { progress: A.p(0.2 + i * 0.08, 0.5, 'glide'), color: '#FFD54F', lw: 4, head: 12, alpha: 0.7 });
    }
  }, { alpha: sunA });
}

A.with(() => {
  ctx.save();
  ctx.beginPath(); ctx.arc(ex, ey, er, 0, Math.PI * 2); ctx.clip();
  ctx.fillStyle = '#14466e'; ctx.fillRect(ex - er, ey - er, er * 2, er * 2);
  const conts = [[0.0, -0.3, 0.35, 0.3], [1.3, 0.2, 0.28, 0.45], [2.4, -0.45, 0.4, 0.22], [3.6, 0.35, 0.3, 0.3], [4.8, -0.05, 0.25, 0.4], [5.6, 0.5, 0.2, 0.15]];
  ctx.fillStyle = '#3fae7a';
  for (const c of conts) {
    const lon = c[0] + rot;
    const cz = Math.cos(lon);
    if (cz <= 0) continue;
    const cx = ex + er * Math.sin(lon);
    const cy = ey + er * c[1];
    ctx.beginPath();
    ctx.ellipse(cx, cy, er * c[2] * cz, er * c[3], 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // lado noche (derecha, lejos del sol)
  const g = ctx.createLinearGradient(ex - er * 0.1, 0, ex + er * 0.4, 0);
  g.addColorStop(0, 'rgba(3,8,20,0)'); g.addColorStop(1, 'rgba(3,8,20,0.82)');
  ctx.fillStyle = g; ctx.fillRect(ex - er, ey - er, er * 2, er * 2);
  ctx.restore();
  A.lib.hatch(ctx, [[ex + er * 0.3, ey - er], [ex + er, ey - er], [ex + er, ey + er], [ex + er * 0.3, ey + er]], { angle: 45, spacing: 14, width: 1.2, color: 'rgba(160,200,255,0.18)' });
  A.circle(ex, ey, er, { stroke: '#cfe8ff', lw: 4 });
  // flecha de giro
  const ga = rot % (Math.PI * 2);
  ctx.save(); ctx.strokeStyle = acc; ctx.lineWidth = 5; ctx.globalAlpha = 0.8;
  ctx.beginPath(); ctx.arc(ex, ey, er + 22, ga, ga + 1.2); ctx.stroke(); ctx.restore();
}, { x: ex, y: ey, scale: eScale });

// "NO CAMBIA" (fase 1)
const lab1 = A.pop(kNo, 0.45) * (1 - A.p(k2 - 0.25, 0.3, 'accelExit'));
if (lab1 > 0.01) A.label('NO CAMBIA', 540, 1060, { size: 64, bg: acc, color: '#06121f', scale: lab1 });
// "IGUAL" junto a la Tierra pequeña
const lab2 = A.pop(k2 + 0.55, 0.45);
if (lab2 > 0.01) A.text('IGUAL', 270, 1700, { size: 50, color: '#cfe8ff', weight: '800', align: 'center', alpha: A.clamp(lab2) });

// ---------- RELOJ ----------
const cS = A.pop(k2, 0.5);
if (cS > 0.01) {
  const cx = 540, cy = 720, R = 240;
  const pJ = A.p(k2 + 0.35, 0.55, 'snapSettle');
  const shake = (t > k2 + 0.8 && t < k2 + 1.05) ? 10 : 0;
  A.with(() => {
    A.circle(cx, cy, R, { fill: '#0e2236', stroke: acc, lw: 10, glow: 25 });
    for (let i = 0; i < 12; i++) {
      const a = i / 12 * Math.PI * 2;
      const r1 = i % 3 === 0 ? R - 50 : R - 32;
      A.line([[cx + Math.sin(a) * r1, cy - Math.cos(a) * r1], [cx + Math.sin(a) * (R - 16), cy - Math.cos(a) * (R - 16)]], { stroke: '#ffffff', lw: i % 3 === 0 ? 8 : 4 });
    }
    const hour = 7 + pJ;
    const ha = hour / 12 * Math.PI * 2;
    const ma = pJ * Math.PI * 2;
    const sa = (t * 6) % 1 * Math.PI * 2 * 0 + t * 2.5;
    A.line([[cx, cy], [cx + Math.sin(ha) * 120, cy - Math.cos(ha) * 120]], { stroke: '#ffffff', lw: 16 });
    A.line([[cx, cy], [cx + Math.sin(ma) * 185, cy - Math.cos(ma) * 185]], { stroke: '#ffffff', lw: 9 });
    A.line([[cx, cy], [cx + Math.sin(sa) * 200, cy - Math.cos(sa) * 200]], { stroke: acc, lw: 3 });
    A.circle(cx, cy, 14, { fill: acc });
  }, { x: cx, y: cy, scale: cS, shake });

  const plus = A.pop(k2 + 0.8, 0.45);
  if (plus > 0.01) A.label('+1 h', 830, 500, { size: 70, bg: '#FFD54F', color: '#1a1200', scale: plus });

  if (t > kRel) A.rings(cx, cy, kRel, { count: 3, speed: 420, gap: 0.18, maxR: 420, color: acc, lw: 5, alpha: 0.6 });
  const relS = A.pop(kRel, 0.45);
  if (relS > 0.01) A.label('RELOJ', 540, 1040, { size: 72, bg: acc, color: '#06121f', scale: relS });
}
A.flash(k2 + 0.8, 0.25, 0.25);

// ---------- ACUERDO ----------
if (t > kAc - 0.05) {
  const xs = [610, 760, 910];
  const lp = A.p(kAc + 0.2, 0.5, 'glide');
  A.line([[xs[0], 1560], [xs[2], 1560]], { stroke: acc, lw: 4, progress: lp, dash: [10, 10] });
  xs.forEach((x, i) => {
    const s = A.pop(kAc + i * 0.1, 0.45);
    if (s > 0.01) A.with(() => A.person(x, 1700, { scale: 0.75, color: i === 1 ? acc : '#ffffff' }), { x, y: 1700, scale: s });
  });
  const ag = A.pop(kAc + 0.35, 0.45);
  if (ag > 0.01) A.label('ACUERDO', 760, 1410, { size: 54, bg: '#ffffff', color: '#06121f', scale: ag });
}

const W=A.W, AC=A.accent;
A.bg('#0a1024','#05070f',true);
const kInv=A.k('invierno,',0.333), kAtr=A.k('atrasa',1.0), kHora=A.k('hora,',1.667);
const kAm=A.k('amanezca',2.667), kTemp=A.k('temprano',3.333), kGente=A.k('gente',4.333);
const kTrab=A.k('trabajo',5.333), kCol=A.k('colegio.',6.333);

// ---- cielo cálido + horizonte + sol ----
const pSky=A.p(kAm-0.2,1.6,'softInOut');
if(pSky>0){
  const g=ctx.createLinearGradient(0,420,0,1100);
  g.addColorStop(0,'rgba(255,170,80,0)');g.addColorStop(1,'rgba(255,150,60,'+(0.32*pSky)+')');
  ctx.fillStyle=g;ctx.fillRect(40,420,1000,680);
}
const pHor=A.p(kAm-0.3,0.7,'glide');
if(pHor>0){
  const pSun=A.p(kAm,1.4,'snapSettle');
  const sx=780, sy=A.lerp(1180,860,pSun);
  ctx.save();ctx.beginPath();ctx.rect(0,400,W,700);ctx.clip();
  if(pSun>0){
    ctx.save();ctx.translate(sx,sy);ctx.rotate(t*0.4);
    for(let i=0;i<12;i++){ctx.rotate(Math.PI/6);A.line([[0,95],[0,130+8*Math.sin(t*4+i)]],{stroke:'#ffcc55',lw:8,alpha:pSun});}
    ctx.restore();
    A.sun(sx,sy,80);
  }
  ctx.restore();
  A.line([[60,1100],[1020,1100]],{stroke:A.pal?A.pal.lineWhite:'#fff',lw:6,progress:pHor});
  if(t>kAm+0.4) A.rings(sx,sy,kAm+0.4,{count:3,speed:220,gap:60,maxR:300,color:'#ffcc55',lw:4,alpha:0.5});
  const pT=A.pop(kTemp,0.5);
  if(t>kTemp) A.label('AMANECE ANTES',sx,700,{size:46,bg:'#ffb347',color:'#0a1024',scale:pT});
}

// ---- reloj protagonista ----
const pMove=A.p(kAm-0.1,0.8,'whip');
const cx=A.lerp(540,290,pMove), cy=A.lerp(720,600,pMove), r=A.lerp(230,140,pMove);
const sIn=A.pop(0,0.5);
const pBack=A.p(kAtr,1.0,'whip');
const h=8-pBack; // 8:00 -> 7:00
const sh=(t>kHora&&t<kHora+0.35)?10*(1-(t-kHora)/0.35):0;
A.with(()=>{
  A.circle(cx,cy,r,{fill:'#111a36',stroke:'#ffffff',lw:8});
  const pts=[];for(let i=0;i<=24;i++){const a=i/24*Math.PI*2;pts.push([cx+Math.cos(a)*r*0.96,cy+Math.sin(a)*r*0.96]);}
  if(A.lib&&A.lib.hatch) A.lib.hatch(ctx,pts,{angle:0.7,spacing:22,width:1.5,color:'rgba(140,170,255,0.18)'});
  for(let i=0;i<12;i++){const a=i/12*Math.PI*2-Math.PI/2;
    A.line([[cx+Math.cos(a)*r*0.82,cy+Math.sin(a)*r*0.82],[cx+Math.cos(a)*r*0.93,cy+Math.sin(a)*r*0.93]],{stroke:'#fff',lw:i%3?4:9});}
  // arco de retroceso
  if(pBack>0&&pBack<1.0||(t>kAtr&&t<kAtr+1.6)){
    const al=t<kAtr+1.0?1:A.clamp(1-(t-kAtr-1.0)/0.6);
    ctx.save();ctx.strokeStyle=AC;ctx.globalAlpha=0.6*al;ctx.lineWidth=14;ctx.beginPath();
    ctx.arc(cx,cy,r*0.7,-Math.PI/2-pBack*Math.PI*2,-Math.PI/2);ctx.stroke();ctx.restore();
  }
  const am=(h%1)*Math.PI*2-Math.PI/2, ah=(h/12)*Math.PI*2-Math.PI/2;
  A.line([[cx,cy],[cx+Math.cos(ah)*r*0.5,cy+Math.sin(ah)*r*0.5]],{stroke:'#ffffff',lw:16});
  A.line([[cx,cy],[cx+Math.cos(am)*r*0.78,cy+Math.sin(am)*r*0.78]],{stroke:AC,lw:10});
  const asec=t*Math.PI*2/1.5;
  A.line([[cx,cy],[cx+Math.cos(asec)*r*0.85,cy+Math.sin(asec)*r*0.85]],{stroke:'#ff5577',lw:3,alpha:0.8});
  A.circle(cx,cy,14,{fill:AC});
  const hh=Math.floor(h+1e-6), mm=Math.round((h-hh)*60)%60;
  const hs=(mm===0?Math.round(h):hh)+':'+String(mm).padStart(2,'0');
  A.text(hs,cx,cy+r+70,{size:A.lerp(78,54,pMove),color:pBack>=1?AC:'#ffffff',weight:'900',align:'center'});
},{x:cx,y:cy,scale:sIn,shake:sh});

// INVIERNO
const pInv=A.pop(kInv,0.5);
if(t>kInv) A.label('INVIERNO',cx,cy-r-45,{size:A.lerp(44,34,pMove),bg:'#8fd3ff',color:'#0a1024',scale:pInv});
// -1 HORA
if(t>kHora){
  const ps=A.pop(kHora,0.45);
  A.with(()=>{A.label('−1 HORA',cx+r*0.85,cy-r*0.75,{size:A.lerp(64,40,pMove),bg:AC,color:'#06100a'});},{x:cx+r*0.85,y:cy-r*0.75,scale:ps,rot:-0.12});
  A.rings(cx+r*0.85,cy-r*0.75,kHora,{count:2,speed:400,gap:70,maxR:220,color:AC,lw:5,alpha:0.6});
  A.flash(kHora,0.25,0.25);
}

// ---- zona secundaria: gente al trabajo y al colegio ----
const gy=1680;
const pG=A.p(kGente-0.3,0.6,'softLand');
if(pG>0){
  A.line([[80,gy],[1000,gy]],{stroke:'#ffffff',lw:4,progress:pG,alpha:0.7});
  const glow=A.clamp(pSky);
