 tM=A.k('mundial',4.67), tH=A.k('husos',5.33), tMa=A.k('mantienen',6.33), tV=A.k('voluntarios',6.67);
const tR=tH+0.55;
// ---- teléfono
const pm=A.p(tCo,0.7,'glide');
const px=A.lerp(540,290,pm), py=770;
const ps=A.pop(0.05,0.5)*(1+0.04*Math.sin(t*3)*(t<tCo?1:0));
const changed=t>=tR;
A.with(()=>{
  A.rect(px-150,py-280,300,560,{r:44,fill:'#1a1230',stroke:'#ffffff',lw:6});
  A.rect(px-128,py-250,256,500,{r:28,fill:'#0b0718'});
  A.rect(px-40,py-240,80,14,{r:7,fill:'#2a2045'});
  const cp=A.p(tR,0.35,'crashIn');
  const clock=changed?'23:00':'00:00';
  A.text(clock,px,py-40,{size:84,color:changed?ac:'#ffffff',weight:'800',align:'center',scale:1});
  if(t>tCo&&!changed){
