    A.text('BUSCANDO'+dots,px,py+60,{size:28,color:'#ffffff',alpha:0.7,align:'center',weight:'700'});
  }
  if(changed){
    A.with(()=>A.label('-1 HORA',px,py+70,{size:38,bg:ac,color:'#0b0718'}),{x:px,y:py+70,scale:A.pop(tR,0.45)});
    A.rings(px,py-40,tR,{count:2,speed:420,maxR:220,color:ac,lw:4});
  }
