},{x:px,y:py,scale:ps,shake:t>tR&&t<tR+0.25?6:0});
// signo de pregunta
if(t>tQ-0.1){
  const qa=1-A.p(tCo+0.3,0.4,'accelExit');
  A.with(()=>A.text('?',px+150,py-300,{size:160,color:ac,weight:'900',align:'center',alpha:qa}),
   {x:px+150,y:py-330,scale:A.pop(tQ-0.1,0.45),rot:0.15*Math.sin(t*4)});
}
// ---- base de datos
const dx=800, dy0=560;
const ds=A.pop(tB-0.25,0.5);
if(t>tB-0.25){
  A.with(()=>{
    for(let i=2;i>=0;i--){
      const y=dy0+i*115;
      ctx.save();
      ctx.fillStyle='#22163f';
      ctx.beginPath();ctx.ellipse(dx,y+95,150,40,0,0,Math.PI);ctx.lineTo(dx-150,y);ctx.ellipse(dx,y,150,40,0,Math.PI,0,true);ctx.closePath();ctx.fill();
      ctx.restore();
      A.lib.hatch(ctx,[[dx-150,y],[dx-60,y+30],[dx-60,y+130],[dx-150,y+95]],{angle:0.8,spacing:12,width:2,color:'rgba(179,136,255,0.35)'});
      A.line([[dx-150,y],[dx-150,y+95]],{stroke:'#ffffff',lw:4});
      A.line([[dx+150,y],[dx+150,y+95]],{stroke:'#ffffff',lw:4});
      ctx.save();ctx.strokeStyle='#ffffff';ctx.lineWidth=4;
      ctx.beginPath();ctx.ellipse(dx,y+95,150,40,0,0,Math.PI);ctx.stroke();
      ctx.fillStyle='#2e2052';ctx.beginPath();ctx.ellipse(dx,y,150,40,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();
      for(let j=0;j<3;j++){
        const on=(Math.floor(t*6)+i*2+j)%4===0;
        A.circle(dx+60+j*24,y+65,7,{fill:on?ac:'#4a3a70',glow:on?14:0});
      }
    }
  },{x:dx,y:dy0+150,scale:ds});
  A.with(()=>A.label('BASE DE DATOS',dx,980,{size:36,bg:'#ffffff',color:'#0b0718'}),{x:dx,y:980,scale:A.pop(tB+0.1,0.45)});
}
// ---- paquetes celular -> base
const sx=px+150, sy=py-200, ex=dx-150, ey=dy0+40, cx=(sx+ex)/2, cy=Math.min(sy,ey)-180;
const bez=(u)=>[(1-u)*(1-u)*sx+2*(1-u)*u*cx+u*u*ex,(1-u)*(1-u)*sy+2*(1-u)*u*cy+u*u*ey];
if(t>tCo+0.3){
  const pts=[];for(let i=0;i<=24;i++)pts.push(bez(i/24));
  A.line(pts,{stroke:ac,lw:3,dash:[10,12],alpha:0.6,progress:A.p(tCo+0.3,0.6,'softLand')});
  if(t<tR){
    for(let k=0;k<3;k++){
      const u=((t-tCo-0.3)*0.9+k/3)%1;
      const [qx,qy]=bez(u);
      A.circle(qx,qy,10,{fill:'#ffffff',glow:16});
    }
  }
  if(t>tR-0.5&&t<tR){
    const u=1-A.p(tR-0.5,0.5,'gentleIn');const [qx,qy]=bez(u);
    A.circle(qx,qy,16,{fill:ac,glow:24});
  }
}
// ---- globo husos horarios
const gx=540, gy=1520, gr=130;
if(t>tM-0.1){
  A.line([[dx,dy0+330],[dx,1430],[gx+gr*0.7,1430]],{stroke:ac,lw:3,dash:[8,10],alpha:0.5,progress:A.p(tM-0.1,0.5,'softLand')});
  const gs=A.pop(tM,0.5);
  A.with(()=>{
    A.circle(gx,gy,gr,{fill:'#1a1230',stroke:'#ffffff',lw:5});
    ctx.save();ctx.beginPath();ctx.arc(gx,gy,gr-3,0,Math.PI*2);ctx.clip();
    const hp=A.p(tH,0.8,'cruise');
    const n=12, off=(t*40)%(gr*2/6);
    for(let i=-2;i<n+2;i++){
      if(i/n>hp)break;
      const x=gx-gr+i*(gr*2/6)/2+off;
      if(i%2===0){ctx.fillStyle='rgba(179,136,255,0.45)';ctx.fillRect(x,gy-gr,gr/6,gr*2);}
    }
    ctx.restore();
    for(let i=1;i<4;i++){
      ctx.save();ctx.strokeStyle='rgba(255,255,255,0.4)';ctx.lineWidth=2;
      ctx.beginPath();ctx.ellipse(gx,gy,gr*i/4,gr,0,0,Math.PI*2);ctx.stroke();ctx.restore();
    }
    A.line([[gx-gr,gy],[gx+gr,gy]],{stroke:'#ffffff',lw:2,alpha:0.4});
  },{x:gx,y:gy,scale:gs});
  if(t>tH){
    A.with(()=>A.label('HUSOS HORARIOS',gx,gy,{size:34,bg:'#0b0718',color:ac}),{x:gx,y:gy,scale:A.pop(tH+0.1,0.45)});
  }
}
// ---- voluntarios
const vol=[[150,0],[290,1],[790,2],[930,3]];
vol.forEach(([vx,i])=>{
  const st=tMa+0.15+i*0.12;
  if(t<st)return;
  const s=A.pop(st,0.45);
  A.with(()=>A.person(vx,1700,{scale:0.7,color:i%2?ac:'#ffffff'}),{x:vx,y:1700,scale:s});
  const hx=vx, hy=1560;
  const tx=gx+(vx<gx?-gr:gr)*0.9, ty=gy;
  A.line([[hx,hy],[tx,ty]],{stroke:'#ffffff',lw:2,dash:[6,8],alpha:0.35,progress:A.p(st+0.1,0.4,'softLand')});
  const u=((t-st)*1.4)%1;
  A.circle(A.lerp(hx,tx,u),A.lerp(hy,ty,u),6,{fill:ac,glow:12,alpha:A.clamp((t-st-0.2)*4)});
});
if(t>tV){
  A.with(()=>A.label('VOLUNTARIOS',gx,1715,{size:40,bg:ac,color:'#0b0718'}),{x:gx,y:1715,scale:A.pop(tV,0.45)});
}

const ac = A.accent;
A.bg('#0b1020', '#1c0b12');
const kC = A.k('Chile', 1.0), kCam = A.k('cambiado', 1.67), kF = A.k('fechas', 2.33),
  kU = A.k('última', 3.0), kCel = A.k('celulares', 4.0), kM = A.k('mostrado', 4.67),
  kH = A.k('hora', 5.33, 2), kE = A.k('equivocada', 5.67);

// ---------- CALENDARIO ----------
const pIn = A.p(0, 0.6, 'snapSettle');
const pm = A.p(kCel - 0.25, 0.7, 'whip');
const cx = 540;
const cy = A.lerp(760, 520, pm) + (1 - pIn) * 300;
const sc = A.lerp(1, 0.48, pm);
const shk = (t > kU && t < kU + 0.45) ? 9 : 0;
A.with(() => {
  // sombra
  A.rect(cx - 222, cy - 226, 460, 480, { r: 30, fill: 'rgba(0,0,0,0.45)' });
  A.rect(cx - 230, cy - 240, 460, 480, { r: 30, fill: '#f3f1ea', stroke: '#ffffff', lw: 4 });
  A.rect(cx - 230, cy - 240, 460, 120, { r: 30, fill: ac });
  A.rect(cx - 230, cy - 160, 460, 40, { fill: ac });
  A.text('ABRIL', cx, cy - 178, { size: 64, color: '#fff', weight: '900', align: 'center' });
  for (let i = 0; i < 2; i++) {
    const bx = cx - 120 + i * 240;
    A.rect(bx - 12, cy - 270, 24, 70, { r: 12, fill: '#2a2f45' });
  }
  // fecha vieja
  const po = A.p(kF, 0.45, 'accelExit');
  if (po < 1) {
    A.text('6', cx - po * 220, cy + 80, { size: 240, color: '#1a1a2a', weight: '900', align: 'center', alpha: 1 - po });
    const ps = A.p(kCam, 0.35, 'whip');
    if (ps > 0) A.line([[cx - 110 - po * 220, cy + 120], [cx + 110 - po * 220, cy - 10]], { stroke: ac, lw: 18, progress: ps, alpha: 1 - po });
  }
  // fecha nueva
  const pn = A.pop(kF + 0.12, 0.45);
  if (t > kF + 0.12) {
    A.with(() => {
      A.text('13', cx, cy + 80, { size: 240, color: ac, weight: '900', align: 'center' });
    }, { x: cx, y: cy + 60, scale: pn });
  }
  // sello DECRETO
  if (t > kC) {
    const ss = A.lerp(2.2, 1, A.p(kC, 0.3, 'crashIn'));
    A.with(() => {
      A.rect(cx - 330, cy + 150, 250, 80, { r: 10, stroke: ac, lw: 7, fill: 'rgba(255,61,61,0.12)' });
      A.text('DECRETO', cx - 205, cy + 192, { size: 44, color: ac, weight: '900', align: 'center' });
    }, { x: cx - 205, y: cy + 190, scale: ss, rot: -0.2, alpha: A.p(kC, 0.15) });
  }
  // reloj de última hora
  if (t > kU) {
    const bx = cx + 220, by = cy - 230;
    A.with(() => {
      A.circle(bx, by, 72, { fill: '#ffffff', stroke: ac, lw: 8, glow: ac });
      for (let i = 0; i < 12; i++) {
        const a = i / 12 * Math.PI * 2;
        A.circle(bx + Math.cos(a) * 54, by + Math.sin(a) * 54, 4, { fill: '#1a1a2a' });
      }
      const sp = (t - kU);
      const a1 = sp * 14 - Math.PI / 2, a2 = sp * 1.6 - Math.PI / 2;
      A.line([[bx, by], [bx + Math.cos(a1) * 50, by + Math.sin(a1) * 50]], { stroke: ac, lw: 6 });
      A.line([[bx, by], [bx + Math.cos(a2) * 32, by + Math.sin(a2) * 32]], { stroke: '#1a1a2a', lw: 9 });
      A.circle(bx, by, 7, { fill: '#1a1a2a' });
    }, { x: bx, y: by, scale: A.pop(kU, 0.4) });
    if (pm < 0.5) A.rings(bx, by, kU, { count: 3, speed: 420, gap: 0.18, maxR: 260, color: ac, lw: 6 });
  }
}, { x: cx, y: cy, scale: sc * A.lerp(0.7, 1, pIn), shake: shk, alpha: pIn });

// etiqueta ÚLTIMA HORA
if (t > kU) {
  const out = A.p(kCel - 0.3, 0.3, 'accelExit');
  if (out < 1) A.label('¡ÚLTIMA HORA!', 540, 1085, { size: 60, bg: ac, color: '#fff', scale: A.pop(kU + 0.1, 0.45) * (1 - out) });
}

// ---------- CELULARES ----------
const xs = [220, 540, 860];
const wrong = [null, '09:00', '07:00'];
const order = [1, 0, 2];
for (let j = 0; j < 3; j++) {
  const i = order[j];
  const st = kCel + 0.05 + j * 0.13;
  if (t < st) continue;
  const x = xs[i], y = 905;
  const isW = wrong[i] !== null;
  const flipped = isW && t > kM + i * 0.12;
  let jx = 0, jy = 0;
  if (flipped) {
    const r = A.rand(Math.floor(t * 14) + i * 97);
    const g = t > kE ? 16 : 7;
    jx = (r() - 0.5) * g; jy = (r() - 0.5) * g * 0.5;
  }
  const drop = A.p(st, 0.5, 'snapSettle');
  A.with(() => {
    const err = isW && t > kE;
    A.rect(x - 112, y - 195, 224, 390, { r: 34, fill: '#141a2e', stroke: err ? ac : '#e8ecff', lw: err ? 8 : 5, glow: err ? ac : null });
    A.rect(x - 96, y - 165, 192, 330, { r: 18, fill: flipped ? '#2a0d14' : '#0d1428' });
    A.rect(x - 30, y - 183, 60, 9, { r: 4, fill: '#3a4060' });
    const blink = Math.floor(t * 2) % 2 === 0;
    const tm = flipped ? wrong[i] : (blink ? '08:00' : '08 00');
    if (flipped) {
