      A.line([[x + 70, y - 120], [x - 70, y + 120]], { stroke: ac, lw: 16, progress: A.p(kE + 0.15, 0.3, 'whip') });
    }
    if (!isW && t > kE) {
      A.with(() => {
        A.circle(x, y + 125, 30, { fill: '#ffffff' });
        A.line([[x - 14, y + 125], [x - 3, y + 137], [x + 16, y + 112]], { stroke: '#0b1020', lw: 7 });
      }, { x: x, y: y + 125, scale: A.pop(kE + 0.1) });
    }
  }, { x: x, y: y, scale: A.lerp(0.3, 1, drop), alpha: drop, shake: (isW && t > kE && t < kE + 0.4) ? 10 : 0 });
  if (isW && t > kE) A.rings(x, y, kE, { count: 2, speed: 380, gap: 0.2, maxR: 240, color: ac, lw: 5 });
