// ---------- HORA REAL (zona secundaria) ----------
if (t > kH - 0.1) {
  const s = A.pop(kH - 0.1, 0.45);
  A.with(() => {
    A.rect(300, 1380, 480, 280, { r: 30, fill: 'rgba(255,255,255,0.06)', stroke: '#ffffff', lw: 4 });
    A.text('HORA REAL', 540, 1440, { size: 42, color: '#c9d0f0', weight: '800', align: 'center' });
    A.text('08:00', 540, 1570, { size: 140, color: '#ffffff', weight: '900', align: 'center' });
  }, { x: 540, y: 1520, scale: s });
}

A.flash(kE, 0.3, 0.35);

const W=A.W, acc=A.accent, ICE='#8EC5FF';
A.bg('#0b1630','#050a18');
const kS=A.k('Síguenos',0), kC=A.k('Chile',1.667), kM=A.k('mundo.',2.667), kP=A.k('¿Prefieres',3.0), kV=A.k('verano',4.333), kI=A.k('invierno?',5.667);
const split=A.p(kP-0.1,0.8,'whip');
const intro=A.pop(0.05,0.5);
const cx=540, cy=A.lerp(760,560,split), r=A.lerp(230,115,split);
// Ondas del "mundo"
if(t>kM && split<1) A.rings(cx,cy,kM,{count:3,speed:500,gap:0.25,maxR:420,color:acc,lw:5,alpha:0.7*(1-split)});
A.with(()=>{
  A.circle(cx,cy,r,{fill:'#0f2250',stroke:'#ffffff',lw:7,glow:acc});
  // meridianos globo
  const g=A.p(kM,0.6,'softLand')*(1-split);
  if(g>0){
    ctx.save();ctx.globalAlpha=g*0.8;ctx.strokeStyle=ICE;ctx.lineWidth=3;
    const rot=t*0.8;
    for(let i=0;i<4;i++){const w=Math.abs(Math.cos(rot+i*Math.PI/4))*r;ctx.beginPath();ctx.ellipse(cx,cy,Math.max(w,1),r*0.97,0,0,Math.PI*2);ctx.stroke();}
    for(const f of[-0.5,0,0.5]){ctx.beginPath();ctx.ellipse(cx,cy+f*r,r*Math.sqrt(1-f*f)*0.98,r*0.08,0,0,Math.PI*2);ctx.stroke();}
    ctx.restore();
  }
  for(let i=0;i<12;i++){const a=i/12*Math.PI*2;const r1=r*0.84,r2=r*(i%3==0?0.7:0.77);
    A.line([[cx+Math.cos(a)*r1,cy+Math.sin(a)*r1],[cx+Math.cos(a)*r2,cy+Math.sin(a)*r2]],{stroke:'#ffffff',lw:i%3==0?7:4,alpha:1-g*0.6});}
  // aguja
  const spin=-Math.PI/2+t*5;
  const left=Math.PI*0.75, right=Math.PI*0.25;
  const pv=A.p(kV-0.1,0.5,'snapSettle'), pi=A.p(kI-0.1,0.5,'snapSettle');
  let ang=A.lerp(spin, -Math.PI/2+kP*5, split);
  ang=A.lerp(ang,left+Math.PI*2*Math.ceil((ang-left)/(Math.PI*2)),pv);
  if(pv>=1) ang=A.lerp(left,right,pi);
  A.line([[cx,cy],[cx+Math.cos(ang)*r*0.72,cy+Math.sin(ang)*r*0.72]],{stroke:acc,lw:A.lerp(12,8,split)});
  A.line([[cx,cy],[cx+Math.cos(ang*0.3-1)*r*0.45,cy+Math.sin(ang*0.3-1)*r*0.45]],{stroke:'#ffffff',lw:A.lerp(12,7,split),alpha:1-split});
  A.circle(cx,cy,r*0.07,{fill:acc});
},{x:cx,y:cy,scale:intro});
// CHILE
const cl=A.pop(kC,0.45);
if(t>kC && split<1) A.label('CHILE',cx,cy+r+80,{size:58,bg:acc,color:'#0b1630',scale:cl,alpha:1-split});
// Tarjetas
if(split>0){
  const fv=A.p(kV,0.45,'popOver'), fi=A.p(kI,0.45,'popOver');
  const sV=1+0.14*fv*(1-fi), sI=1+0.14*fi;
  const aV=1-0.55*fi, aI=fv>0&&fi<0.1?0.55:1;
  const y=880;
  const lx=A.lerp(540,285,split), rx=A.lerp(540,795,split);
  // verano
  A.with(()=>{
    A.rect(lx-140,y-170,280,340,{r:30,fill:'#1a2a10',stroke:acc,lw:6,glow:fv>0.5?acc:null});
    A.sun(lx,y-40,62+6*Math.sin(t*4));
    A.text('VERANO',lx,y+105,{size:52,color:acc,weight:900,align:'center'});
    A.label('+1 h',lx,y-185,{size:40,bg:acc,color:'#0b1630',scale:A.pop(kP+0.4)});
  },{x:lx,y:y,scale:split*sV,alpha:split*aV});
  // invierno
  A.with(()=>{
    A.rect(rx-140,y-170,280,340,{r:30,fill:'#0d1c3a',stroke:ICE,lw:6,glow:fi>0.5?ICE:null});
    A.circle(rx,y-40,62,{fill:ICE,glow:ICE});
    A.circle(rx+28,y-58,54,{fill:'#0d1c3a'});
    A.particles(14,7,(i,rnd)=>{const sx=rx-120+rnd()*240;const sy=y-160+((rnd()*240+t*60*(0.5+rnd()))%240);A.circle(sx,sy,3+rnd()*3,{fill:'#ffffff',alpha:0.8});});
    A.text('INVIERNO',rx,y+105,{size:48,color:ICE,weight:900,align:'center'});
    A.label('−1 h',rx,y-185,{size:40,bg:ICE,color:'#0b1630',scale:A.pop(kP+0.6)});
  },{x:rx,y:y,scale:split*sI,alpha:split*aI});
  if(t>kV) A.flash(kV,0.2,0.15);
  if(t>kI) A.flash(kI,0.2,0.15);
  // VS
  const vs=A.pop(kP+0.3);
  A.text('o',540,y+20,{size:70,color:'#ffffff',weight:900,align:'center',alpha:split*(0.4+0.6*A.p(4.667,0.3)),stroke:'#0b1630',strokeWidth:8});
}
// Seguir
A.follow(540,1540,kS+0.1,kS+1.3);
const q=A.p(kI+0.2,0.5,'softLand');
if(q>0) A.text('Comenta tu elección',540,1680,{size:44,color:'#ffffff',weight:700,align:'center',alpha:q});
